+                                    <p class="card-text mb-1 text-muted small">@task.Assignee</p>
+                                    <div class="d-flex justify-content-between align-items-center mb-1">
+                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
+                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
+                                    </div>
+                                    <div class="d-flex gap-1">
+                                        @if (colIndex > 0)
+                                        {
+                                            <button class="btn btn-outline-secondary btn-sm"
+                                                    @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex - 1])">
+                                                &larr; Move Left
+                                            </button>
+                                        }
+                                        @if (colIndex < Columns.Length - 1)
+                                        {
+                                            <button class="btn btn-outline-secondary btn-sm"
+                                                    @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex + 1])">
+                                                Move Right &rarr;
+                                            </button>
+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        }
+
+                        @if (addingToColumn == colName)
+                        {
+                            <div class="card border-primary mb-2">
+                                <div class="card-body p-2">
+                                    <div class="mb-2">
+                                        <input type="text" class="form-control form-control-sm"
+                                               placeholder="Title" @bind="newTitle" />
+                                    </div>
+                                    <div class="mb-2">
+                                        <input type="text" class="form-control form-control-sm"
+                                               placeholder="Assignee" @bind="newAssignee" />
+                                    </div>
+                                    <div class="mb-2">
+                                        <select class="form-select form-select-sm" @bind="newPriority">
+                                            <option value="High">High</option>
+                                            <option value="Medium">Medium</option>
+                                            <option value="Low">Low</option>
+                                        </select>
+                                    </div>
+                                    <div class="mb-2">
+                                        <input type="date" class="form-control form-control-sm"
+                                               @bind="newDueDate" />
+                                    </div>
+                                    <div class="d-flex gap-1">
+                                        <button class="btn btn-primary btn-sm"
+                                                @onclick="SaveNewTaskAsync">Save</button>
+                                        <button class="btn btn-outline-secondary btn-sm"
+                                                @onclick="CancelAdd">Cancel</button>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                    </div>
+                    <div class="card-footer">
+                        <button class="btn btn-outline-primary btn-sm w-100"
+                                @onclick="() => StartAdd(colName)">
+                            + Add Task
+                        </button>
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem>? allTasks;
+    private bool isLoading = true;
+    private string? errorMessage;
+    private string searchQuery = string.Empty;
+
+    // Add-task form state
+    private string? addingToColumn;
+    private string newTitle = string.Empty;
+    private string newAssignee = string.Empty;
+    private string newPriority = "Medium";
+    private DateTime newDueDate = DateTime.Today.AddDays(7);
+
+    private IEnumerable<TaskItem> FilteredTasks =>
+        string.IsNullOrWhiteSpace(searchQuery)
+            ? allTasks!
+            : allTasks!.Where(t => t.Title.Contains(searchQuery, StringComparison.OrdinalIgnoreCase));
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var task = allTasks!.First(t => t.Id == taskId);
+            allTasks![allTasks.IndexOf(task)] = task with { Status = newStatus };
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to move task: {ex.Message}";
+        }
+    }
+
+    private void StartAdd(string column)
+    {
+        addingToColumn = column;
+        newTitle = string.Empty;
+        newAssignee = string.Empty;
+        newPriority = "Medium";
+        newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => addingToColumn = null;
+
+    private async Task SaveNewTaskAsync()
+    {
+        if (string.IsNullOrWhiteSpace(newTitle)) return;
+
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
+
+            // CreateTaskAsync returns the task with default status; update to the target column if needed
+            if (created.Status != addingToColumn)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, addingToColumn!);
+                created = created with { Status = addingToColumn! };
+            }
+
+            allTasks!.Add(created);
+            addingToColumn = null;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to create task: {ex.Message}";
+        }
+    }
+
+    private static string GetPriorityClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+}
+

